# Biology 4 (Zoology): animal tissues and human physiology (NEET unit 5 and
# the animal part of unit 2: breathing, body fluids and circulation,
# excretion, locomotion, neural and chemical coordination). Key written
# first; numbers asserted below.
from math import isclose

# cardiac output: 70 mL x 72 beats
assert isclose(70 * 72 / 1000, 5.04)
# lung volumes: TV 500, IRV 2500, ERV 1000, RV 1100
TV, IRV, ERV, RV = 500, 2500, 1000, 1100
assert TV + IRV + ERV + RV == 5100 and TV + IRV + ERV == 4000
assert ERV + RV == 2100 and TV + IRV == 3000

